@once
<script>
window.finalGradeManager=function(data){return {
    ...data,expanded:data.expanded,predicate:'',page:1,perPage:10,bulkOpen:false,bulkFields:[],bulkNumbers:'',bulkValue:'',bulkError:'',bulkNotice:'',selectedCells:[],selecting:false,selectionStart:null,
    init(){this.original=JSON.stringify({modules:this.modules,ta:this.ta,components:this.components});this.initial=JSON.parse(JSON.stringify(this.rows));this.$watch('predicate',()=>this.page=1);if(this.embedded){for(const name of ['globalSearch','globalKelompok','globalShift'])this.$watch(name,()=>this.page=1)}},
    get configDirty(){return this.role==='koor' && JSON.stringify({modules:this.modules,ta:this.ta,components:this.components})!==this.original},
    get payload(){const students={};for(const row of this.rows){const old=this.initial.find(r=>r.id===row.id);const scores={};for(const c of this.components){const value=row.extras[c.id]??'',before=old.extras[c.id]??'';if((value==='')!==(before==='')||(value!==''&&Number(value)!==Number(before)))scores[c.id]=value===''?null:String(value).replace(',','.')}if(Object.keys(scores).length)students[row.id]={version:row.extra_version||0,scores}}const payload={version:this.version,students};if(this.configDirty)payload.settings={modules:this.modules,ta:this.ta,components:this.components};return payload},
    get dirty(){return this.editable && (this.configDirty || Object.keys(this.payload.students).length>0)},
    get weightTotal(){return Number(this.modules||0)+Number(this.ta||0)+this.components.reduce((sum,c)=>sum+Number(c.bobot||0),0)},
    addColumn(){if(this.role!=='koor'||!this.editable||this.components.length>=3)return;this.components.push({id:crypto.randomUUID(),nama:'',bobot:0})},
    removeColumn(id){this.components=this.components.filter(c=>c.id!==id)},
    get visibleRows(){return this.rows.filter(r=>(this.predicate===''||(this.letter(r)||'pending')===this.predicate)&&(!this.embedded||((this.globalSearch===''||r.name.toLowerCase().includes(this.globalSearch.toLowerCase())||String(r.nim).includes(this.globalSearch))&&(this.globalKelompok===''||String(r.group??'')===this.globalKelompok)&&(this.globalShift===''||String(r.shift??'')===this.globalShift))))},
    get pageRows(){return this.visibleRows.slice((this.page-1)*this.perPage,this.page*this.perPage)},get totalPages(){return Math.max(1,Math.ceil(this.visibleRows.length/this.perPage))},
    span(id,type){const rows=this.pageRows,i=rows.findIndex(r=>r.id===id);if(i<0)return 0;const same=(a,b)=>a.shift===b.shift&&(type==='shf'||a.group===b.group);if(i>0&&same(rows[i-1],rows[i]))return 0;let n=1;while(i+n<rows.length&&same(rows[i],rows[i+n]))n++;return n},
    // Rational arithmetic mirrors the server: no intermediate floating-point rounding.
    fraction(value){const s=String(value).replace(',','.');if(s.includes('/'))return s.split('/').map(BigInt);const [a,b='']=s.split('.');return [BigInt(a+b),10n**BigInt(b.length)]},
    total(row){if(!this.dirty)return row.final;if(this.weightTotal!==100||!row.calculation?.module_exact||!row.calculation?.ta_exact)return null;try{let n=0n,d=1n;const values=[[row.calculation.module_exact,this.modules],[row.calculation.ta_exact,this.ta]];for(const c of this.components){const value=row.extras[c.id];if(value===undefined||value===null||value===''||!/^\d{1,3}(\.\d{1,2})?$/.test(String(value))||Number(value)>100)return null;values.push([value,c.bobot])}for(const [value,weight] of values){const [a,b]=this.fraction(value);n=n*b+a*BigInt(weight)*d;d*=b}d*=100n;const rounded=(n*100n*2n+d)/(2n*d);return (rounded/100n).toString()+'.'+(rounded%100n).toString().padStart(2,'0')}catch{return null}},
    letter(row){if(!this.dirty)return row.letter;const value=this.total(row);if(value===null||!row.cohort)return null;const rule=this.rules.find(r=>row.cohort>=r.from&&(r.to===null||row.cohort<=r.to));return rule?.bands.find(b=>Number(value)>=Number(b.minimum))?.letter||null},
    display(value){return value===null||value===undefined?'Belum dinilai':String(value).replace('.',',')},
    predicateStyle(row){const colors={A:['#F0FDF4','#15803D'],AB:['#DDF2EE','#174E43'],B:['#D1F0F9','#0C4D6E'],BC:['linear-gradient(135deg,#D1F0F9,#F9ECCB)','#353849'],C:['#FBD982','#5B3D1E'],D:['#FFBD4C','#5B3D1E'],E:['#FADAE1','#710E21']};const c=colors[this.letter(row)]||['#F8F9FB','#666D80'];return {background:c[0],color:c[1]}},
    assessmentOptions(){return this.components.map(c=>({value:c.id,label:c.nama||'Kolom baru'}))},assessmentLabel(key){return this.assessmentOptions().find(c=>c.value===key)?.label||'Pilih kolom penilaian'},availableAssessmentOptions(index){return this.assessmentOptions().filter(c=>this.bulkFields[index]===c.value||!this.bulkFields.includes(c.value))},addAssessmentField(){const next=this.components.find(c=>!this.bulkFields.includes(c.id));if(next)this.bulkFields.push(next.id)},removeAssessmentField(index){this.bulkFields.splice(index,1)},
    beginSelection(row,key){if(!this.editable)return;this.selecting=true;this.selectionStart={id:row.id,key};this.extendSelection(row,key)},
    extendSelection(row,key){if(!this.selecting)return;const rows=this.pageRows,keys=this.components.map(c=>c.id),a=rows.findIndex(r=>r.id===this.selectionStart.id),b=rows.findIndex(r=>r.id===row.id),c=keys.indexOf(this.selectionStart.key),d=keys.indexOf(key);if(Math.min(a,b,c,d)<0)return;this.selectedCells=[];for(let i=Math.min(a,b);i<=Math.max(a,b);i++)for(let j=Math.min(c,d);j<=Math.max(c,d);j++)this.selectedCells.push({id:rows[i].id,key:keys[j]})},
    isSelected(row,key){return this.selectedCells.some(c=>c.id===row.id&&c.key===key)},
    finishSelection(){if(!this.selecting)return;this.selecting=false;if(this.selectedCells.length<2){this.selectedCells=[];return}this.bulkFields=[...new Set(this.selectedCells.map(c=>c.key))];this.bulkNumbers=[...new Set(this.selectedCells.map(c=>this.visibleRows.findIndex(r=>r.id===c.id)+1))].join(', ');this.bulkOpen=true},
    closeBulk(){this.bulkOpen=false;this.selectedCells=[];this.bulkError='';this.bulkValue=''},
    applyBulk(){const value=String(this.bulkValue).replace(',','.');if(!/^\d{1,3}(\.\d{1,2})?$/.test(value)||Number(value)>100||!this.bulkFields.length){this.bulkError='Pilih kolom dan masukkan nilai 0–100.';return}const numbers=new Set();for(const part of this.bulkNumbers.replace(/[–—]/g,'-').split(',')){const m=part.trim().match(/^(\d+)(?:\s*-\s*(\d+))?$/);if(!m||Number(m[1])<1||Number(m[2]||m[1])<Number(m[1])||Number(m[2]||m[1])>this.visibleRows.length){this.bulkError='Nomor mahasiswa tidak valid.';return}for(let n=Number(m[1]);n<=Number(m[2]||m[1]);n++)numbers.add(n)}for(const n of numbers)for(const key of this.bulkFields)this.visibleRows[n-1].extras[key]=value;this.closeBulk()},
}}
</script>
@endonce
